// Test: stackalloc a Span of native-sized integers (nint / nuint)
Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Span<nuint> unsignedSpan = stackalloc nuint[4];
for (int i = 0; i < unsignedSpan.Length; i++)
    unsignedSpan[i] = (nuint)(i * 100);

Console.WriteLine($"nint  span: [{string.Join(", ", signedSpan.ToArray())}]");
Console.WriteLine($"nuint span: [{string.Join(", ", unsignedSpan.ToArray())}]");
Console.WriteLine($"nint size : {sizeof(nint)} bytes (IntPtr.Size = {IntPtr.Size})");

